'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var sin = require( '@stdlib/math/base/special/sin' );
var cos = require( '@stdlib/math/base/special/cos' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
var rfftf = require( '@stdlib/fft/base/fftpack/rfftf' );
var rfftb = require( '@stdlib/fft/base/fftpack/rfftb' );


// VARIABLES //

// var nd = [ 120, 91, 54, 49, 32, 28, 24, 8, 4, 3, 2 ];
var nd = [ 2 ];


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rffti, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function initializes FFT working arrays', function test( t ) { // eslint-disable-line max-statements
	var rftfb;
	var modn;
	var rftf;
	var rftb;
	var sum1;
	var sum2;
	var arg1;
	var sum;
	var arg;
	var np1;
	var nm1;
	var ns2;
	var tol;
	var r2;
	var r3;
	var r1;
	var nz;
	var xh;
	var dt;
	var cf;
	var n;
	var j;
	var x;
	var y;
	var w;
	var k;
	var i;

	for ( nz = 1; nz <= nd.length; nz++ ) {
		n = nd[ nz - 1 ];

		x = new Float64Array( n );
		y = new Float64Array( n );
		xh = new Float64Array( n );
		w = new Float64Array( (n*2)+34 );

		modn = n % 2;
		np1 = n + 1;
		nm1 = n - 1;

		for ( j = 1; j <= np1; j++ ) {
			x[ j - 1 ] = sin( j * SQRT2 );
			y[ j - 1 ] = x[ j - 1 ];
			xh[ j - 1 ] = x[ j - 1 ];
		}

		// TEST SUBROUTINES RFFTI,RFFTF AND RFFTB:
		rffti( n, w, 1, 0 );
		dt = TWO_PI / n;
		ns2 = floor( ( n + 1 ) / 2 );
		if ( ns2 > 1 ) {
			for ( k = 2; k <= ns2; k++ ) {
				sum1 = 0.0;
				sum2 = 0.0;
				arg = ( k - 1 ) * dt;
				for ( i = 1; i <= n; i++ ) {
					arg1 = ( i - 1 ) * arg;
					sum1 += x[ i - 1 ] * cos( arg1 );
					sum2 += x[ i - 1 ] * sin( arg1 );
				}
				y[ ( k << 1 ) - 3 ] = sum1;
				y[ ( k << 1 ) - 2 ] = -sum2;
			}
		}
		sum1 = 0.0;
		sum2 = 0.0;
		for ( i = 1; i <= nm1; i += 2 ) {
			sum1 += x[ i - 1 ];
			sum2 += x[ i ];
		}
		if ( modn === 1 ) {
			sum1 += x[ n - 1 ];
		}
		y[ 0 ] = sum1 + sum2;
		if ( modn === 0 ) {
			y[ n - 1 ] = sum1 - sum2;
		}
		rfftf( n, x, 1, 0, w, 1, 0 );
		rftf = 0.0;
		for ( i = 1; i <= n; i++ ) {
			// Computing MAX:
			r2 = rftf;
			r1 = x[ i - 1 ] - y[ i - 1 ];
			r3 = abs( r1 );
			rftf = max( r2, r3 );
			x[ i - 1 ] = xh[ i - 1 ];
		}
		rftf /= n;

		for ( i = 1; i <= n; i++ ) {
			sum = x[ 0 ] * 0.5;
			arg = ( i - 1 ) * dt;
			if ( ns2 > 1 ) {
				for ( k = 2; k <= ns2; k++ ) {
					arg1 = ( k - 1 ) * arg;
					sum += ( x[ ( k << 1 ) - 3 ] * cos( arg1 ) ) - ( x[ ( k << 1 ) - 2 ] * sin( arg1 ) ); // eslint-disable-line max-len
				}
			}
			if ( modn === 0 ) {
				sum += pow( -1, i - 1 ) * 0.5 * x[ n - 1 ];
			}
			y[ i - 1 ] = 2 * sum;
		}

		rfftb( n, x, 0, w, 0 );
		rftb = 0.0;
		for ( i = 1; i <= n; i++ ) {
			// Computing MAX:
			r2 = rftb;
			r1 = x[ i - 1 ] - y[ i - 1 ];
			r3 = abs( r1 );
			rftb = max( r2, r3 );
			x[ i - 1 ] = xh[ i - 1 ];
			y[ i - 1 ] = xh[ i - 1 ];
		}

		rfftb( n, y, 0, w, 0 );
		rfftf( n, y, 1, 0, w, 1, 0 );
		cf = 1.0 / n;
		rftfb = 0.0;
		for ( i = 1; i <= n; i++ ) {
			// Computing MAX:
			r2 = rftfb;
			r1 = ( cf * y[ i - 1 ] ) - x[ i - 1 ];
			r3 = abs( r1 );
			rftfb = max( r2, r3 );
		}
		console.log( x );
		console.log( y );

		tol = 1e-3;
		t.ok( rftf <= tol, 'forward transform error: ' + rftf + ' (expected <= ' + tol + ')' );
		t.ok( rftb <= tol, 'backward transform error: ' + rftb + ' (expected <= ' + tol + ')' );
		t.ok( rftfb <= tol, 'forward-backward transform error: ' + rftfb + ' (expected <= ' + tol + ')' );
	}

	t.end();
});
